create table "public"."shidduchim_external_links" (
    "id" bigint generated by default as identity not null,
    "account_id" bigint not null,
    "created_at" timestamp with time zone not null default now(),
    "shidduchim_id" bigint not null,
    "url" text not null,
    "label" text
);


alter table "public"."shidduchim_external_links" enable row level security;

CREATE INDEX shidduchim_external_links_account_id_idx ON public.shidduchim_external_links USING btree (account_id);

CREATE UNIQUE INDEX shidduchim_external_links_pkey ON public.shidduchim_external_links USING btree (id);

CREATE INDEX shidduchim_external_links_shidduchim_id_idx ON public.shidduchim_external_links USING btree (shidduchim_id);

alter table "public"."shidduchim_external_links" add constraint "shidduchim_external_links_pkey" PRIMARY KEY using index "shidduchim_external_links_pkey";

alter table "public"."shidduchim_external_links" add constraint "shidduchim_external_links_account_id_fkey" FOREIGN KEY (account_id) REFERENCES public.accounts(id) ON DELETE CASCADE not valid;

alter table "public"."shidduchim_external_links" validate constraint "shidduchim_external_links_account_id_fkey";

alter table "public"."shidduchim_external_links" add constraint "shidduchim_external_links_shidduchim_id_fkey" FOREIGN KEY (account_id, shidduchim_id) REFERENCES public.shidduchim(account_id, id) ON DELETE CASCADE not valid;

alter table "public"."shidduchim_external_links" validate constraint "shidduchim_external_links_shidduchim_id_fkey";

-- MANUAL ADJUSTMENT: `db diff` drops this REVOKE (AGENTS.md) — starting from
-- "table does not exist", migra's diff never has to strip the privileges
-- `alter default privileges ... grant all on tables to authenticated`
-- (06_grants.sql) auto-grants the moment CREATE TABLE runs above, so without
-- this statement `authenticated` would keep TRIGGER/REFERENCES/TRUNCATE on
-- top of the four grants below, diverging from a from-schema-files build
-- (same class of gap as migration 20260730045700's medical_notes precedent).
revoke all on table "public"."shidduchim_external_links" from "anon", "authenticated";

set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.account_has_domain_data(p_account_id bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select
       exists (select 1 from public.singles where account_id = p_account_id)
    or exists (select 1 from public.shadchanim where account_id = p_account_id)
    or exists (select 1 from public."references" where account_id = p_account_id)
    or exists (select 1 from public.shidduchim where account_id = p_account_id)
    or exists (select 1 from public.resumes where account_id = p_account_id)
    or exists (select 1 from public.reference_links where account_id = p_account_id)
    or exists (select 1 from public.date_records where account_id = p_account_id)
    or exists (select 1 from public.redts where account_id = p_account_id)
    or exists (select 1 from public.shidduch_schools where account_id = p_account_id)
    or exists (select 1 from public.shidduchim_external_links where account_id = p_account_id)
    or exists (select 1 from public.interactions where account_id = p_account_id)
    or exists (select 1 from public.identity_signals where account_id = p_account_id)
    or exists (select 1 from public.inbox_items where account_id = p_account_id)
    or exists (select 1 from public.tasks where account_id = p_account_id);
$function$
;

grant delete on table "public"."shidduchim_external_links" to "authenticated";

grant insert on table "public"."shidduchim_external_links" to "authenticated";

grant select on table "public"."shidduchim_external_links" to "authenticated";

grant update on table "public"."shidduchim_external_links" to "authenticated";

grant delete on table "public"."shidduchim_external_links" to "service_role";

grant insert on table "public"."shidduchim_external_links" to "service_role";

grant references on table "public"."shidduchim_external_links" to "service_role";

grant select on table "public"."shidduchim_external_links" to "service_role";

grant trigger on table "public"."shidduchim_external_links" to "service_role";

grant truncate on table "public"."shidduchim_external_links" to "service_role";

grant update on table "public"."shidduchim_external_links" to "service_role";


  create policy "Shidduchim external links scoped to account"
  on "public"."shidduchim_external_links"
  as permissive
  for all
  to authenticated
using ((account_id = public.current_context_id()))
with check ((account_id = public.current_context_id()));


CREATE TRIGGER set_shidduchim_external_links_account_id BEFORE INSERT ON public.shidduchim_external_links FOR EACH ROW EXECUTE FUNCTION public.set_account_id_default();

CREATE TRIGGER validate_shidduchim_external_links_household_scope BEFORE INSERT OR UPDATE OF account_id ON public.shidduchim_external_links FOR EACH ROW EXECUTE FUNCTION public.enforce_household_scope();
